  "implementation": "def solve(case):
    if not isinstance(case, dict) or 'threshold' not in case or 'calls' not in case:
        raise ValueError("case must have 'threshold' and 'calls'")
    threshold = case['threshold']
    if not isinstance(threshold, (int, float)):
        raise ValueError("threshold must be number")
    calls = case['calls']
    if not isinstance(calls, list):
        raise ValueError("calls must be list")
    diagnostics = []
    accepted_ids = []
    for call in calls:
        if not isinstance(call, dict):
            raise ValueError("each call must be dict")
        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']
        for r in required:
            if r not in call:
                raise ValueError(f"call missing {r}")
        call_id = call['call_id']
        if not isinstance(call_id, str):
            raise ValueError("call_id must be string")
        loss_without = call['loss_without_call']
        loss_with = call['loss_with_call']
        if not isinstance(loss_without, (int, float)) or not isinstance(loss_with, (int, float)):
            raise ValueError("losses must be numbers")
        pred_tokens = call['prediction_tokens']
        if not isinstance(pred_tokens, int) or pred_tokens <= 0:
            raise ValueError("prediction_tokens must be positive integer")
        parseable = call['parseable']
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be boolean")
        gain = loss_without - loss_with
        normalized_gain = round(gain / pred_tokens, 8)
        accepted = parseable and normalized_gain >= threshold
        if accepted:
            accepted_ids.append(call_id)
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": normalized_gain
        })
    return {
        "accepted_call_ids": accepted_ids,
        "diagnostics": diagnostics
    }"
}
